START TRANSACTION;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    ALTER TABLE "ADM_PRODUCT_EVENT_RULE_CHARGES" ALTER COLUMN "AMOUNT_BASE_CODE" TYPE character varying(80);
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    CREATE TABLE "FCT_DISBURSEMENT_CHARGES" (
        "DISBURSEMENT_CHARGE_ID" bigint GENERATED BY DEFAULT AS IDENTITY,
        "DISBURSEMENT_ID" bigint NOT NULL,
        "PRODUCT_EVENT_RULE_ID" bigint NOT NULL,
        "PRODUCT_ID" bigint NOT NULL,
        "RULE_CHARGE_ID" bigint NOT NULL,
        "RULE_CODE" character varying(80) NOT NULL,
        "RULE_NAME" character varying(200) NOT NULL,
        "CALCULATION_METHOD" character varying(25) NOT NULL,
        "BASE_CODE" character varying(80),
        "BASE_AMOUNT" numeric(18,2),
        "UNITS" numeric(20,6),
        "FIXED_AMOUNT" numeric(18,2),
        "RATE_PERCENT" numeric(18,8),
        "PER_UNIT_AMOUNT" numeric(18,2),
        "SPREAD_PERCENT" numeric(18,8),
        "DAY_COUNT_BASIS" integer,
        "CHARGE_AMOUNT" numeric(18,2) NOT NULL,
        "TAX_RATE_PERCENT" numeric(9,6) NOT NULL,
        "TAX_AMOUNT" numeric(18,2) NOT NULL,
        "TOTAL_AMOUNT" numeric(18,2) NOT NULL,
        "CURRENCY_ID" bigint NOT NULL,
        "CHARGE_TIMING_CODE" character varying(25) NOT NULL,
        "INCOME_RECOGNITION_CODE" character varying(20) NOT NULL,
        "DUE_DATE" date,
        "STATUS_CODE" character varying(30) NOT NULL,
        "COLLECTED_AMOUNT" numeric(18,2) NOT NULL,
        "WAIVED_AMOUNT" numeric(18,2) NOT NULL,
        "IS_GL_POSTED" boolean NOT NULL,
        "GL_JOURNAL_REF" character varying(100),
        "CALCULATION_AT" timestamp with time zone NOT NULL,
        "CREATED_BY" character varying(100) NOT NULL,
        "CREATED_AT" timestamp with time zone NOT NULL,
        "UPDATED_BY" character varying(100),
        "UPDATED_AT" timestamp with time zone,
        "ROW_VERSION" integer NOT NULL,
        CONSTRAINT "PK_FCT_DISBURSEMENT_CHARGES" PRIMARY KEY ("DISBURSEMENT_CHARGE_ID"),
        CONSTRAINT "FK_FCT_DISBURSEMENT_CHARGES_ADM_PRODUCT_EVENT_RULES" FOREIGN KEY ("PRODUCT_EVENT_RULE_ID") REFERENCES "ADM_PRODUCT_EVENT_RULES" ("PRODUCT_EVENT_RULE_ID") ON DELETE RESTRICT,
        CONSTRAINT "FK_FCT_DISBURSEMENT_CHARGES_ADM_PRODUCT_EVENT_RULE_CHARGES" FOREIGN KEY ("RULE_CHARGE_ID") REFERENCES "ADM_PRODUCT_EVENT_RULE_CHARGES" ("RULE_CHARGE_ID") ON DELETE RESTRICT,
        CONSTRAINT "FK_FCT_DISBURSEMENT_CHARGES_FCT_DISBURSEMENTS" FOREIGN KEY ("DISBURSEMENT_ID") REFERENCES "FCT_DISBURSEMENTS" ("DISBURSEMENT_ID") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    CREATE TABLE "FCT_REPAYMENTS" (
        "SCHEDULE_ID" bigint GENERATED BY DEFAULT AS IDENTITY,
        "DISBURSEMENT_ID" bigint NOT NULL,
        "INSTALLMENT_NO" integer NOT NULL,
        "DUE_DATE" date NOT NULL,
        "ADJUSTED_DUE_AT" timestamp with time zone,
        "OPENING_PRINCIPAL" numeric(20,4),
        "OUTSTANDING_PRINCIPAL" numeric(20,4),
        "OUTSTANDING_INTEREST" numeric(20,4),
        "TOTAL_INSTALLMENT" numeric(20,4),
        "CLOSING_PRINCIPAL" numeric(20,4),
        "PAID_PRINCIPAL" numeric(20,4),
        "PAID_INTEREST" numeric(20,4),
        "PAID_FEE" numeric(20,4),
        "PAID_PENALTY" numeric(20,4),
        "PRINCIPAL_DUE" numeric(20,4),
        "INTEREST_DUE" numeric(20,4),
        "PENALTY_DUE" numeric(20,4),
        "FEE_DUE" numeric(20,4),
        "INTEREST_RATE" numeric(9,6),
        "INDEX_RATE_ID" bigint,
        "DAY_COUNT" integer,
        "DAY_COUNT_BASIS" character varying(10),
        "LAST_PAYMENT_AT" timestamp with time zone,
        "DAYS_OVERDUE" integer,
        "STATUS_CODE" character varying(50) NOT NULL,
        "SCHEDULE_VERSION" integer,
        "IS_CURRENT_VERSION" boolean NOT NULL,
        "RECALC_REASON" character varying(500),
        "CREATED_BY" character varying(100) NOT NULL,
        "CREATED_AT" timestamp with time zone NOT NULL,
        "UPDATED_BY" character varying(100),
        "UPDATED_AT" timestamp with time zone,
        "ROW_VERSION" integer NOT NULL,
        CONSTRAINT "PK_FCT_REPAYMENTS" PRIMARY KEY ("SCHEDULE_ID"),
        CONSTRAINT "FK_FCT_REPAYMENTS_FCT_DISBURSEMENTS" FOREIGN KEY ("DISBURSEMENT_ID") REFERENCES "FCT_DISBURSEMENTS" ("DISBURSEMENT_ID") ON DELETE RESTRICT
    );
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    CREATE INDEX "IX_FCT_DISBURSEMENT_CHARGES_DISBURSEMENT_ID_STATUS_CODE" ON "FCT_DISBURSEMENT_CHARGES" ("DISBURSEMENT_ID", "STATUS_CODE");
    END IF;
END $EF$;

