    CREATE INDEX "IX_FCT_DISBURSEMENT_CHARGES_PRODUCT_EVENT_RULE_ID" ON "FCT_DISBURSEMENT_CHARGES" ("PRODUCT_EVENT_RULE_ID");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    CREATE INDEX "IX_FCT_DISBURSEMENT_CHARGES_RULE_CHARGE_ID" ON "FCT_DISBURSEMENT_CHARGES" ("RULE_CHARGE_ID");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    CREATE UNIQUE INDEX "UQ_FCT_DISBURSEMENT_CHARGES_DISBURSEMENT_ID_RULE_CHARGE_ID" ON "FCT_DISBURSEMENT_CHARGES" ("DISBURSEMENT_ID", "RULE_CHARGE_ID");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    CREATE INDEX "IX_FCT_REPAYMENTS_DISBURSEMENT_ID_IS_CURRENT_VERSION_DUE_DATE" ON "FCT_REPAYMENTS" ("DISBURSEMENT_ID", "IS_CURRENT_VERSION", "DUE_DATE");
    END IF;
END $EF$;

DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "SYS_EF_MIGRATION_HISTORY" WHERE "MigrationId" = '20261030195724_DisbursementProcess') THEN
    INSERT INTO "SYS_EF_MIGRATION_HISTORY" ("MigrationId", "ProductVersion")
